import Foundation

/// Real certificates for `CertificatePinningTests` (#2159, #2160), as base64 DER.
///
/// - `isrgRootX1` / `isrgRootX2`: Let's Encrypt's roots, from
///   https://letsencrypt.org/certs/isrgrootx1.pem and .../isrg-root-x2.pem.
/// - `letsEncryptChain`: the chain https://valid-isrgrootx1.letsencrypt.org served on
///   2026-11-05 (leaf, YR1, ISRG Root YR cross-signed by ISRG Root X1), captured with
///   `openssl s_client -showcerts`. The leaf is valid 2026-11-04 .. 2027-02-02, so tests
///   evaluate it at `letsEncryptChainVerifyDate`, not at the current time.
/// - `isrgRootYR` / `isrgRootYE`: the Generation-Y roots, self-signed, from
///   https://letsencrypt.org/certs/gen-y/root-yr.pem and .../root-ye.pem (#2505).
///   `isrgRootYRByX1` / `isrgRootYEByX2` are the copies cross-signed by X1 / X2, which
///   the server presents today; they carry the same keys.
/// - `letsEncryptChainYE`: the chain https://valid-isrgrootx2.letsencrypt.org served on
///   2026-11-06 (leaf, YE1, ISRG Root YE cross-signed by ISRG Root X2). Leaf valid
///   2026-10-29 .. 2027-01-27.
/// - `unpinnedCA` / `unpinnedLeaf`: a throwaway P-256 CA and a leaf it signed for
///   `letsEncryptHost` (valid 2026-11-06 .. 2027-02-04), made with `openssl req -x509` /
///   `openssl x509 -req`. Anchored explicitly in tests it yields a chain that is VALID but
///   carries none of the pinned keys — what a mis-issued certificate from another CA is.
/// - `selfSignedImpostorLeaf`: a self-signed P-256 certificate for the same host name
///   (`openssl req -x509 -newkey ec ...`) — what an on-path attacker can mint.
enum CertificatePinningFixtures {
    static let letsEncryptHost = "valid-isrgrootx1.letsencrypt.org"

    /// 2026-11-20T00:00:00Z — inside every fixture certificate's validity window.
    static let letsEncryptChainVerifyDate = Date(timeIntervalSince1970: 1_795_132_800)

    static let isrgRootX1 = ""

    static let isrgRootX2 = ""

    static let letsEncryptHostYE = "valid-isrgrootx2.letsencrypt.org"

    static let isrgRootYR = ""

    static let isrgRootYE = ""

    static let isrgRootYRByX1 = ""

    static let isrgRootYEByX2 = ""

    static let letsEncryptChainYE = [
        "",
        "",
        "",
    ]

    static let unpinnedCA = ""

    static let unpinnedLeaf = ""

    static let letsEncryptChain = [
        "",
        "",
        "",
    ]

    static let selfSignedImpostorLeaf = ""
}
